on\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [126, 1987, 319, 2020], \"page_id\": 79}], \"content\": \"December 2011\", \"description\": null, \"id\": 10, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [670, 97, 989, 130], \"page_id\": 80}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1446, 85, 1494, 130], \"page_id\": 80}], \"content\": \"75\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [295, 179, 1368, 325], \"page_id\": 80}], \"content\": \"SECTION III.\\u2014Liabilities to, and Claims on, Unaffiliated Foreigners Reported by Nonbanking Business Enterprises in the United States\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [464, 332, 1200, 377], \"page_id\": 80}], \"content\": \"TABLE CM-III-1.\\u2014Total Liabilities and Claims by Type\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [444, 387, 1213, 420], \"page_id\": 80}], \"content\": \"[Position at end of period in millions of dollars. Source: Treasury International Capital Reporting System]\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 424, 1506, 1763], \"page_id\": 80}], \"content\": \"<table><tr><th>Type of liability or claim</th><th colspan=\\\"3\\\">Calendar year</th><th colspan=\\\"3\\\">2010</th><th colspan=\\\"3\\\">2011</th></tr><tr><th></th><th>2007</th><th>2008</th><th>2009 r</th><th>June r</th><th>Sept. r</th><th>Dec. r</th><th>Mar.</th><th>June p</th></tr><tr><td>Total liabilities</td><td>103,835</td><td>87,630</td><td>79,272</td><td>86,083</td><td>82,118</td><td>78,876</td><td>75,641</td><td>74,961</td></tr><tr><td>Payable in dollars</td><td>79,161</td><td>69,124</td><td>58,595</td><td>66,591</td><td>63,066</td><td>63,764</td><td>61,866</td><td>61,851</td></tr><tr><td>Financial</td><td>26,474</td><td>18,650</td><td>12,9