escription\": null, \"id\": 14, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [831, 1794, 1390, 1810], \"page_id\": 58}], \"content\": \"http://www.treasury.gov/resource-center/data-chart-center/tic/pages/index.aspx\", \"description\": null, \"id\": 15, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [831, 1817, 1466, 1855], \"page_id\": 58}], \"content\": \"Includes individuals, Government-sponsored enterprises, brokers and dealers, bank personal trusts and estates, corporate and non-corporate businesses, and other investors\", \"description\": null, \"id\": 16, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [1337, 1992, 1488, 2018], \"page_id\": 58}], \"content\": \"December 2014\", \"description\": null, \"id\": 17, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [144, 101, 173, 123], \"page_id\": 59}], \"content\": \"54\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [173, 214, 1461, 250], \"page_id\": 59}], \"content\": \"INTRODUCTION: U.S. Currency and Coin Outstanding and in Circulation\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [138, 271, 798, 573], \"page_id\": 59}], \"content\": \"The U.S. Currency and Coin Outstanding and in Circulation (USCC) statement informs the public of the total face value of currency and coin used as a medium of exchange that is in circulation at the end of a given accounting month. The statement defines the total amount of currency and coin outstanding and the portion deemed to be in circulation. It includes some old and current rare issues that do not circulate or that may do so to a limited extent. Treasury includes them in the statement because the issues were originally intended for general circulation.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 271, 1492, 568], \"page_id\": 59}], \"content\": \"The USCC statement provides a description of the various issues of paper money. It also gives an estimated average of currency and coin held by each individual, using estimates of population from the Bureau of the Census. USCC information has been published by Treasury since 1888, and was published separately until 1983, when it was incorporated into the \\u201cTreasury Bulletin.\\u201d The USCC comes from monthly reports compiled by Treasury offices, U.S. Mint offices, the Federal Reserve banks (FRBs), and the Federal Reserve Board.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [299, 688, 1331, 724], \"page_id\": 59}], \"content\": \"TABLE USCC-1\\u2014Amounts Outstanding and in Circulation, Sept. 30, 2014\", \"description\": null, \"id\": 4, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [679, 735, 947, 757], \"page_id\": 59}], \"content\": \"[Source: Bureau of the Fiscal Service]\", \"description\": null, \"id\": 5, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [144, 757, 1492, 1263], \"page_id\": 59}], \"content\": \"<table><tr><th>Currency</th><th>Total currency and coin (1)</th><th>Total currency (2)</th><th>Federal Reserve notes 1 (3)</th><th>U.S. notes (4)</th><th>Currency no longer issued (5)</th></tr><tr><td>Amounts outstanding</td><td>$1,490,734,867,880</td><td>$1,445,044,480,815</td><td>$1,444,563,981,247</td><td>$240,089,666</td><td>$240,409,902</td></tr><tr><td colspan=\\\"6\\\">Less amounts held by:</td></tr><tr><td>The Treasury</td><td>256,846,204</td><td>64,313,645</td><td>64,055,929</td><td>7,505</td><td>250,211</td></tr><tr><td>FRBs</td><td>200,153,157,584</td><td>198,222,641,210</td><td>198,222,639,079</td><td>-</td><td>2,131</td></tr><tr><td>Amounts in circulation</td><td>$1,290,324,864,092</td><td>$1,246,757,525,960</td><td>$1,246,277,286,239</td><td>$240,082,161</td><td>$240,157,560</td></tr></table>\", \"description\": null, \"id\": 6, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [142, 1362, 1492, 1832], \"page_id\": 59}], \"content\": \"<table><tr><th>Coins <sup>2</sup></th><th>Total (1)</t