nge(2007, 2014):\n    print(f\"FY {year}: ${data[year]} million\")\n\nprint(\"\\n=== Year-over-Year Growth Rates ===\")\nyoy_growth = []\nfor year in range(2008, 2014):\n    growth = (data[year] - data[year-1]) / data[year-1] * 100\n    yoy_growth.append(growth)\n    print(f\"FY {year-1} -> FY {year}: {growth:.4f}%\")\n\navg_yoy = sum(yoy_growth) / len(yoy_growth)\nprint(f\"\\nAverage YoY: {avg_yoy:.6f}%\")\n\nimport math\n# OLS\nX = list(range(1, 8))  # Fiscal year index 1-7\ny = [math.log(data[year]) for year in range(2007, 2014)]\n\nn = len(X)\nsum_x = sum(X)\nsum_y = sum(y)\nsum_xy = sum([X[i]*y[i] for i in range(n)])\nsum_x2 = sum([X[i]**2 for i in range(n)])\n\nslope = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x**2)\nintercept = (sum_y - slope * sum_x) / n\n\nprint(f\"\\n=== OLS Regression: ln(outlays) on fiscal year index ===\")\nprint(f\"Slope: {slope:.6f}\")\nprint(f\"Intercept: {intercept:.6f}\")\n\n# Final rounding\nprint(f\"\\n=== Final Rounded Values ===\")\nprint(f\"Average YoY (hundredths): {round(avg_yoy, 2)}\")\nprint(f\"Slope (thousandths): {round(slope, 3)}\")\nprint(f\"Intercept (thousandths): {round(intercept, 3)}\")\n\n# Note: the problem says \"All numbers should be rounded to the nearest thousandth place\"\n# but also says YoY should be to hundredths. Going with the explicit YoY instruction.\n\n# Final Answer\nprint(f\"\\n[YoY%, slope, intercept]\")\nprint(f\"[{round(avg_yoy, 2)}, {round(slope, 3)}, {round(intercept, 3)}]\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
